var a=[{title:`Beneficii și limite`,text:`Antrenamentul cu greutatea corpului merge oriunde, costă adesea puțin și are multe opțiuni pentru începători. Poate antrena echilibrul, coordonarea, forța și rezistența musculară. Unele tipare sunt mai greu de încărcat precis fără echipament sau fără un punct de ancorare sigur, în special balansările din șold pe care vrei să le faci treptat mai grele și tragerea orizontală.`},{title:`Fă-l provocator`,text:`O flotare la perete poate duce la o flotare înclinată și apoi la una pe podea. Genuflexiunile pot progresa prin mai mult control, pauze și, mai târziu, variante care se concentrează pe un singur picior. Planșele pot deveni mai grele cu o pârghie mai lungă înainte să adaugi timp. Fă un exercițiu mai greu doar cât timp îți poți repeta curat repetările. Acumularea a zeci de repetări ușoare poate muta efectul antrenamentului spre rezistență.`},{title:`Lucrează cu echipamentul tău`,text:`O bară de tracțiuni sigură îți permite să antrenezi tragerea verticală, iar un sistem de suspensie montat ferm îți poate permite să faci ramat. Nu presupune că o masă, o ușă sau o balustradă din casă îți poate ține greutatea corpului. Dacă nu ai un punct de ancorare sigur, alege alt tipar sau folosește benzile elastice și ganterele pe care le ai.`},{title:`Exemplu`,text:`O primă sesiune poate include câte două serii de genuflexiuni la scaun, flotări înclinate, fandări înapoi sprijinite, punți pentru fese și „dead bug”. Alege numărul de repetări după cât de bine controlezi mișcarea și cât de greu ți se pare. Nu există o singură țintă obligatorie. Odihnește-te destul cât să îți păstrezi forma.`},{title:`Folosirea TrainUp`,text:`Dacă nu ai echipament, spune asta în Profil și setează suprafața podelei și dacă săriturile sunt în regulă. Planul alege apoi doar exerciții cu greutatea corpului care se potrivesc cu spațiul, limita de sărituri și nivelul tău. Marchează o bară de tracțiuni ca disponibilă doar dacă este montată în siguranță; altfel planul omite exercițiile care au nevoie de ea.`}];var r=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: ghid despre forță și flexibilitate`,url:`https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};